def rule_fn(row, col) -> bool:
    if col not in ('ProviderNumber','HospitalName'):
        return False
    mapping = {
        '10007': 'mizell memorial hospital',
        '10011': 'st vincents east',
        '10018': 'callahan eye foundation hospital',
        '10006': 'eliza coffee memorial hospital',
        '10005': 'marshall medical center south'
    }
    p = str(row.get('ProviderNumber','')).strip()
    h = str(row.get('HospitalName','')).strip()
    if p in mapping:
        return mapping[p] != h
    return False

def rule_fn(row, col) -> bool:
    if col != 'Score':
